# ---- number check: pipeline/verify.py, embedded verbatim ----
"""Number check for AI texts (PLAN §5): every number in the text must appear in the fact pack.

The check is deliberately strict. A rounded number ("28 %" where the facts say "27,6 %") or
a computed one (a difference of two facts) fails, and the text is generated again or
replaced by the template. Numbers written as words are not checked.

This file has no imports outside the standard library, because the Kaggle notebook embeds
it verbatim.
"""
import re
from decimal import Decimal, InvalidOperation

# 1.625,85 | 1 625,85 (non-breaking space) | 27,6 | 2025 ; thousands groups first, so "1.625" is
# one number. A plain space is not a thousands separator: "za 4 125 €" must stay two numbers.
NUMBER = re.compile(r"(?<![\d,])-?\d{1,3}(?:[.  ]\d{3})+(?:,\d+)?(?![\d])|(?<![\d,.])-?\d+(?:,\d+)?")


def normalise(token):
    t = re.sub(r"[.  ]", "", token).replace(",", ".")
    try:
        return Decimal(t).normalize()
    except InvalidOperation:
        return None


def numbers(text):
    """All numbers in a text, as normalised Decimals with the token they came from."""
    out = []
    for m in NUMBER.finditer(text):
        token = m.group(0).strip()
        v = normalise(token)
        if v is not None:
            out.append((abs(v), token))       # the sign is carried by words ("manjak"), not by "-"
    return out


def allowed(pack):
    vals = set()
    for f in pack["facts"]:
        for part in (f["label"], f["value"]):
            vals |= {v for v, _ in numbers(part)}
    return vals


# "ocjenu 4", "ocjena je 4", "ocjenom 3": the digit after the word must be a grade from the pack
GRADE = re.compile(r"\bocjen\w*(?:\s+(?:je|od|bila|iznosi|za\s+\d{4}\.?(?:\s+godinu)?))*\s+(\d)\b", re.IGNORECASE)


def verify(text, pack):
    """{"ok", "n_brojki", "nepoznate"}. ok only if there is at least one number, every number is
    in the pack, and every grade mentioned is the unit's grade (this year or last year)."""
    ok_vals = allowed(pack)
    found = numbers(text)
    unknown = [tok for v, tok in found if v not in ok_vals]
    grades = {str(g) for g in pack.get("ocjene", [])}
    if grades:
        unknown += [f"ocjena {g}" for g in GRADE.findall(text) if g not in grades]
    return {"ok": bool(found) and not unknown, "n_brojki": len(found), "nepoznate": unknown}

# ---- end of pipeline/verify.py ----

# ---- prompt: pipeline/explain.py SYSTEM, RULES, messages(), feedback(), embedded verbatim ----
SYSTEM = 'Ti si urednik javnog portala o financijama općina, gradova i županija. Pišeš kratka, točna i neutralna objašnjenja za građane na hrvatskom standardnom jeziku.'
RULES = 'Pravila:\n1. Napiši 3 do 5 rečenica, najviše 110 riječi, u jednom odlomku. Bez naslova, natuknica i oznaka (markdown).\n2. Koristi samo činjenice s popisa. Svaku brojku prepiši točno kako je napisana: isti decimalni zarez, isti broj decimala, isti znak % ili €. Ne zaokružuj i ne računaj nove brojke ni razlike.\n3. Počni ocjenom i njezinim opisom riječima. Zatim objasni što najviše utječe na ocjenu: najslabiju sastavnicu (ako je navedena) i jake strane, uz usporedbu s medijanom skupine. Ako postoje upozorenja, pravilo ili napomena o podacima, spomeni ih.\n4. Ton je neutralan i opisan. Ne koristi riječi "loše", "dobro", "uspjeh" ni "neuspjeh". Ne savjetuj, ne nagađaj o uzrocima i ne spominji političare ni stranke.\n5. Naziv jedinice koristi u ovim oblicima: {nom} (nominativ), {gen} (genitiv), {lok} (lokativ).'


def messages(pack):
    n = pack["naziv"]
    lines = "\n".join(f"- {f['label']}: {f['value']}" for f in pack["facts"])
    user = (f"Napiši objašnjenje ocjene financijske stabilnosti {n['gen']} za {pack['year']}. godinu.\n\n"
            + RULES.format(**n) + f"\n\nČINJENICE:\n{lines}")
    return [{"role": "system", "content": SYSTEM}, {"role": "user", "content": user}]


def feedback(unknown):
    return ("Tekst sadrži brojke kojih nema u činjenicama: " + ", ".join(unknown)
            + ". Napiši tekst ponovno i koristi samo brojke s popisa, prepisane točno.")

# ---- end of prompt ----

